using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace PaymentGateway
{
    public enum CircuitState { Closed, Open, HalfOpen }

    public class CircuitBreaker
    {
        private CircuitState _state = CircuitState.Closed;
        private int _failureCount;
        private readonly int _threshold = 3;
        private DateTime _lastFailure;
        private readonly TimeSpan _timeout = TimeSpan.FromSeconds(30);
        private readonly object _lock = new object();

        public bool AllowRequest()
        {
            lock (_lock)
            {
                if (_state == CircuitState.Closed) return true;
                if (_state == CircuitState.Open && DateTime.UtcNow - _lastFailure > _timeout)
                {
                    _state = CircuitState.HalfOpen;
                    return true;
                }
                return _state == CircuitState.HalfOpen;
            }
        }

        public void RecordSuccess() { lock (_lock) { _failureCount = 0; _state = CircuitState.Closed; } }
        public void RecordFailure() { lock (_lock) { _failureCount++; _lastFailure = DateTime.UtcNow; if (_failureCount >= _threshold) _state = CircuitState.Open; } }
    }

    public class EncryptionKeyManager
    {
        private readonly byte[] _masterKey;
        private int _keyVersion = 1;

        public EncryptionKeyManager(byte[] masterKey)
        {
            _masterKey = masterKey;
        }

        public (byte[] key, byte[] iv) DeriveTransactionKey(string transactionId, string merchantId)
        {
            byte[] derivedKey = DeriveKeyMaterial(transactionId, merchantId);
            byte[] iv = GenerateIV();
            return (derivedKey, iv);
        }

        private byte[] DeriveKeyMaterial(string transactionId, string merchantId)
        {
            int currentVersion = Volatile.Read(ref _keyVersion);
            using (var hmac = new HMACSHA256(_masterKey))
            {
                byte[] input = Encoding.UTF8.GetBytes($"payment-key:{merchantId}:{transactionId}:v{currentVersion}");
                return hmac.ComputeHash(input);
            }
        }

        private byte[] GenerateIV()
        {
            byte[] iv = new byte[16];
            using (var rng = RandomNumberGenerator.Create())
            {
                rng.GetBytes(iv);
            }
            return iv;
        }

        public void RotateKeys() { Interlocked.Increment(ref _keyVersion); }
    }

    public class PaymentProcessor
    {
        private readonly CircuitBreaker _circuitBreaker = new CircuitBreaker();
        private readonly EncryptionKeyManager _keyManager;
        private readonly ConcurrentDictionary<string, string> _processedTransactions = new ConcurrentDictionary<string, string>();

        public PaymentProcessor(byte[] masterKey)
        {
            _keyManager = new EncryptionKeyManager(masterKey);
        }

        public async Task<PaymentResult> ProcessPayment(PaymentRequest request)
        {
            if (!_circuitBreaker.AllowRequest())
                return new PaymentResult { Success = false, Error = "Service unavailable" };

            try
            {
                string idempotencyKey = $"{request.MerchantId}:{request.OrderId}";
                if (_processedTransactions.ContainsKey(idempotencyKey))
                    return new PaymentResult { Success = true, TransactionId = _processedTransactions[idempotencyKey] };

                string transactionId = Guid.NewGuid().ToString("N");
                byte[] encryptedCard = EncryptCardData(request.CardNumber, transactionId, request.MerchantId);

                // Simulate gateway call
                await Task.Delay(50);
                bool gatewaySuccess = SimulateGatewayCall(encryptedCard);

                if (gatewaySuccess)
                {
                    _processedTransactions.TryAdd(idempotencyKey, transactionId);
                    _circuitBreaker.RecordSuccess();
                    return new PaymentResult { Success = true, TransactionId = transactionId };
                }

                _circuitBreaker.RecordFailure();
                return new PaymentResult { Success = false, Error = "Gateway declined" };
            }
            catch (Exception ex)
            {
                _circuitBreaker.RecordFailure();
                return new PaymentResult { Success = false, Error = ex.Message };
            }
        }

        private byte[] EncryptCardData(string cardNumber, string transactionId, string merchantId)
        {
            var (key, iv) = _keyManager.DeriveTransactionKey(transactionId, merchantId);
            using (var aes = Aes.Create())
            {
                aes.Key = key;
                aes.IV = iv;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;
                using (var encryptor = aes.CreateEncryptor())
                {
                    byte[] plaintext = Encoding.UTF8.GetBytes(cardNumber);
                    return encryptor.TransformFinalBlock(plaintext, 0, plaintext.Length);
                }
            }
        }

        private bool SimulateGatewayCall(byte[] encryptedData) => encryptedData.Length > 0;
    }

    public class PaymentRequest
    {
        public string MerchantId { get; set; }
        public string OrderId { get; set; }
        public string CardNumber { get; set; }
        public decimal Amount { get; set; }
    }

    public class PaymentResult
    {
        public bool Success { get; set; }
        public string TransactionId { get; set; }
        public string Error { get; set; }
    }
}
